// ── /api/backtest/last-minute — Hosthub creation-date pricing backtest ───────
// Runs against bookings already synced into Postgres (app_data.main.bks), which
// come from Hosthub via /api/sync (quarter-hour auto-sync). Optional ?refresh=1
// triggers a Hosthub sync first when HOSTHUB_API_KEY is configured.
// Also accepts ?source=hosthub to bypass DB and pull Hosthub live (same key).
app.get('/api/backtest/last-minute', async (req, res) => {
  try {
    const lookback = Math.min(365, Math.max(14, parseInt(req.query.lookback || '90', 10) || 90));
    const wantRefresh = String(req.query.refresh || '') === '1';
    const wantLive = String(req.query.source || '') === 'hosthub';

    let bookings = [];
    let apartments = [];
    let source = 'db';
    let syncMeta = null;

    if (wantLive || wantRefresh) {
      const apiKey = SERVER_API_KEY || req.query.api_key || req.headers['x-api-key'] || '';
      if (!apiKey) {
        return res.status(400).json({
          error: 'HOSTHUB_API_KEY not configured on server (and no api_key provided). Cannot refresh from Hosthub.',
          hint: 'Set HOSTHUB_API_KEY on Railway, or run without ?refresh=1 to use already-synced DB bookings.',
        });
      }
      const result = await runSync(apiKey, (msg, type) => {
        // keep quiet in HTTP handler; syncMeta captures outcome
      });
      if (result.error) {
        return res.status(502).json({ error: 'Hosthub sync failed', source: 'hosthub' });
      }
      bookings = result.bookings || [];
      apartments = (result.rentals || []).map(r => ({
        id: String(r.id), name: r.name, city: r.city,
        lat: r.latitude, lng: r.longitude,
      }));
      source = 'hosthub';
      syncMeta = { rentals: apartments.length, bookings: bookings.length };

      // Persist when we have a pool (same path as auto-sync)
      if (pool && bookings.length) {
        try {
          const existing = await pool.query("SELECT data FROM app_data WHERE key = 'main'").catch(() => ({ rows: [] }));
          const prev = existing.rows[0]?.data || {};
          const payload = { ...prev, bks: bookings, apts: prev.apts || [], _savedAt: new Date().toISOString() };
          // Prefer matching rental names onto existing apt configs
          await pool.query(
            `INSERT INTO app_data (key, data) VALUES ('main', $1::jsonb)
             ON CONFLICT (key) DO UPDATE SET data = EXCLUDED.data, updated_at = NOW()`,
            [JSON.stringify(payload)]
          );
          await saveSnapshot(pool, bookings, result.rentals || []);
        } catch (e) {
          console.warn('[backtest] persist after hosthub sync failed:', e.message);
        }
      }
    } else {
      if (!pool) return res.status(503).json({ error: 'No database — cannot load synced Hosthub bookings' });
      const row = await pool.query("SELECT data, updated_at FROM app_data WHERE key = 'main'");
      const data = row.rows[0]?.data;
      if (!data || !Array.isArray(data.bks) || !data.bks.length) {
        return res.status(404).json({
          error: 'No bookings in database yet. Run a Hosthub sync first, or call with ?refresh=1.',
        });
      }
      bookings = data.bks;
      apartments = data.apts || [];
      source = 'db';
      syncMeta = { updatedAt: row.rows[0]?.updated_at || null, bookings: bookings.length, apartments: apartments.length };
    }

    const {
      portfolioBacktest, liveRecommendation, PRICING_HORIZON, PRICELABS, priceLabsGapReport,
    } = require('./lib/last-minute-backtest');

    const NAME_LISTS = {
      thess: ['elysian cornerstone', 'elysian hightower', 'le alex', 'le floor', 'le grace', 'le plaza', 'the skarlatos residence'],
      escape: ['ariti 7', 'ariti7', 'eclectic', 'seaside lavrio', 'sunset nest in fiskardo', 'villa liberty', 'p & g apartment'],
    };
    function categorize(apt) {
      const n = String((apt && apt.name) || '').toLowerCase().replace(/\s+/g, ' ').trim();
      if (NAME_LISTS.thess.some(f => n.includes(f))) return 'thessaloniki';
      if (NAME_LISTS.escape.some(f => n.includes(f))) return 'escape';
      const city = String((apt && apt.city) || '').toLowerCase();
      if (/thessaloniki|salonika/.test(city)) return 'thessaloniki';
      if (/athens|athina|piraeus|pireas|zografou|kallithea/.test(city)) return 'attiki';
      if (apt && apt.lat != null && apt.lng != null) {
        const lat = +apt.lat, lng = +apt.lng;
        if (Math.hypot(lat - 37.9838, lng - 23.7275) < 0.4) return 'attiki';
        if (Math.hypot(lat - 40.6401, lng - 22.9444) < 0.3) return 'thessaloniki';
        return 'escape';
      }
      return 'attiki';
    }

    const aptMap = {};
    for (const a of apartments) aptMap[String(a.id)] = a;
    const byCat = { attiki: [], thessaloniki: [], escape: [] };
    const byApt = {};
    for (const b of bookings) {
      const apt = aptMap[String(b.aptId)] || { name: b.aptName, city: b.city, lat: b.lat, lng: b.lng };
      const cat = categorize(apt);
      byCat[cat].push(b);
      const k = String(b.aptId || b.aptName || '');
      (byApt[k] = byApt[k] || []).push(b);
    }

    const report = portfolioBacktest(byCat, { lookbackDays: lookback });
    const recommendations = [];
    for (const [aptId, bks] of Object.entries(byApt)) {
      const apt = aptMap[aptId] || { id: aptId, name: bks[0]?.aptName || aptId };
      const cat = categorize(apt);
      const horizon = PRICING_HORIZON[cat] || PRICING_HORIZON.default;
      const forwardFill = (() => {
        const today = new Date(); today.setHours(0, 0, 0, 0);
        const end = new Date(today); end.setDate(end.getDate() + horizon.window);
        const booked = new Set();
        const parseDMY = (v) => {
          if (!v) return null;
          const m = String(v).trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
          if (m) return new Date(`${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`);
          const d = new Date(v); return isNaN(d) ? null : d;
        };
        for (const b of bks) {
          if (b.cancelled) continue;
          const guest = String(b.guestName || '').toLowerCase();
          if (['maintenance', 'owner block', 'block', 'owner stay', 'ιδιοκτητης', 'ιδιοχρηση'].includes(guest)) continue;
          const ciD = parseDMY(b.checkIn), coD = parseDMY(b.checkOut);
          if (!ciD || !coD) continue;
          let n = new Date(ciD);
          while (n < coD) {
            if (n >= today && n < end) booked.add(n.toISOString().slice(0, 10));
            n.setDate(n.getDate() + 1);
          }
        }
        return booked.size / horizon.window;
      })();
      const live = liveRecommendation(bks, { category: cat, forwardFill, lookbackDays: lookback });
      if (live.recommendation) {
        recommendations.push({
          aptId, name: apt.name || aptId, category: cat, forwardFill,
          recommendation: live.recommendation,
        });
      }
    }
    recommendations.sort((a, b) => (b.recommendation?.cutPct || 0) - (a.recommendation?.cutPct || 0));

    const withCreated = bookings.filter(b => b.created != null || b.createdOnChannel != null).length;

    res.json({
      ok: true,
      source,
      syncMeta,
      lookbackDays: lookback,
      coverage: {
        bookings: bookings.length,
        withCreated,
        createdCoverage: bookings.length ? withCreated / bookings.length : 0,
        apartments: apartments.length,
      },
      priceLabs: PRICELABS,
      report,
      recommendations: recommendations.slice(0, 80),
      diagnosis: {
        whyHosthubCliFailsWithoutKey:
          'CLI --hosthub needs HOSTHUB_API_KEY in the process env. This cloud agent only had an invalid RAILWAY_TOKEN, so it could not read Railway variables or call Hosthub. Production already syncs Hosthub → Postgres; this endpoint uses that data (or ?refresh=1 with the server key).',
        priceLabsCadence:
          `PriceLabs recalculates daily and pushes to channels ~every ${PRICELABS.channelSyncHoursDefault}h by default. Empty near-term inventory needs Sync Now + deeper Last Minute Prices than the default gradual ${Math.round(PRICELABS.defaultLastMinute.discount * 100)}%/${PRICELABS.defaultLastMinute.windowDays}d when this report shows exceedsPriceLabsDefault.`,
      },
    });
  } catch (e) {
    console.error('[backtest/last-minute]', e);
    res.status(500).json({ error: e.message || String(e) });
  }
});

